options.styles:
.hd {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 100%;
  padding: 0 12px;
}
.hd-title {
  font-size: 26px;
  font-weight: 600;
  letter-spacing: 2px;
  background: linear-gradient(90deg, #8ab8ff, #38bdb0);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hd-sub {
  margin-top: 4px;
  font-size: 13px;
  opacity: 0.65;
}
.hd-clock {
  text-align: right;
}
.hd-time {
  font-size: 28px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  letter-spacing: 1px;
}
.hd-date {
  font-size: 13px;
  opacity: 0.65;
}

options.afterRender:
const time = context.element.querySelector('.hd-time');
const date = context.element.querySelector('.hd-date');
const tick = () => {
  const now = new Date();
  time.textContent = now.toLocaleTimeString('zh-CN', { hour12: false });
  date.textContent = now.toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' });
};

tick();
const timer = setInterval(tick, 1000);
return () => clearInterval(timer);

options.getOption:
const states = [
  ['无', '#8E8E8E'],
  ['失败', '#F2495C'],
  ['成功', '#73BF69'],
  ['同步中', '#56A64B'],
  ['准备同步', '#96D98D'],
  ['暂停', '#FADE2A'],
  ['禁用', '#3D3D3D'],
];
const theme = context.grafana.theme;
const data = context.panel.data.series
  .map((frame) => {
    const [name, color] = states['ABCDEFG'.indexOf(frame.refId)];
    const values = frame.fields.find((f) => f.type === 'number')?.values ?? [];
    return { name, value: values.at(-1) ?? 0, itemStyle: { color } };
  })
  .filter((d) => d.value > 0)
  .sort((a, b) => b.value - a.value);
const total = data.reduce((sum, d) => sum + d.value, 0);

return {
  tooltip: { trigger: 'item', formatter: '{b}<br/>{c} 个 · {d}%' },
  title: {
    text: String(total),
    subtext: '个镜像',
    left: '40%',
    top: '39%',
    textAlign: 'center',
    itemGap: 4,
    textStyle: { fontSize: 34, fontWeight: 600, color: theme.colors.text.primary },
    subtextStyle: { fontSize: 13, color: theme.colors.text.secondary },
  },
  legend: {
    orient: 'vertical',
    left: '70%',
    top: 'middle',
    icon: 'circle',
    itemGap: 16,
    textStyle: { fontSize: 14, color: theme.colors.text.primary },
    formatter: (name) => `${name}   ${data.find((d) => d.name === name)?.value ?? 0}`,
  },
  series: [
    {
      type: 'pie',
      radius: ['56%', '80%'],
      center: ['40%', '50%'],
      padAngle: 2,
      itemStyle: { borderRadius: 8 },
      label: { show: false },
      labelLine: { show: false },
      emphasis: { scale: true, scaleSize: 6 },
      animationType: 'expansion',
      data,
    },
  ],
};

const RING = { name: '镜像占比', colour: (v) => (v >= 0.9 ? '#73BF69' : v >= 0.7 ? '#FF9830' : '#F2495C') };
const theme = context.grafana.theme;
const chart = context.panel.chart;
const value = context.panel.data.series[0]?.fields.find((f) => f.type === 'number')?.values.at(-1) ?? 0;
const color = RING.colour(value);
const radius = Math.max(40, Math.min(chart.getWidth(), chart.getHeight()) / 2 - 22);

return {
  series: [
    {
      type: 'gauge',
      center: ['50%', '54%'],
      radius,
      startAngle: 225,
      endAngle: -45,
      min: 0,
      max: 100,
      progress: { show: true, roundCap: true, width: 14, itemStyle: { color } },
      axisLine: { roundCap: true, lineStyle: { width: 14, color: [[1, theme.colors.background.canvas]] } },
      axisTick: { show: false },
      splitLine: { show: false },
      axisLabel: { show: false },
      pointer: { show: false },
      anchor: { show: false },
      title: { offsetCenter: [0, '70%'], fontSize: 13, color: theme.colors.text.secondary },
      detail: {
        offsetCenter: [0, '0%'],
        valueAnimation: true,
        formatter: '{value}%',
        fontSize: 30,
        fontWeight: 600,
        color: theme.colors.text.primary,
      },
      data: [{ value: Math.round(value * 1000) / 10, name: RING.name }],
    },
  ],
};

