options.styles:
.cd {
  display: flex;
  flex-direction: column;
  gap: 11px;
  padding: 6px 8px;
}
.cd-row {
  display: grid;
  grid-template-columns: 10em 1fr 6.5em;
  align-items: center;
  gap: 14px;
  font-size: 13px;
}
.cd-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cd-track {
  height: 10px;
  border-radius: 5px;
  background: rgba(128, 128, 128, 0.18);
  overflow: hidden;
}
.cd-fill {
  height: 100%;
  border-radius: 5px;
  background: linear-gradient(90deg, #5794f2, #38bdb0);
  transition: width 1s linear;
}
.cd-left {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: #8ab8ff;
}
.late .cd-fill {
  background: linear-gradient(90deg, #f2495c, #ff9830);
}
.late .cd-left {
  color: #f2495c;
}

options.afterRender:
const list = context.element.querySelector('.cd');
const rows = [...context.element.querySelectorAll('.cd-row')].sort((a, b) => a.dataset.at - b.dataset.at);
rows.forEach((row) => list.appendChild(row));

// A bar fills over the last hour before its sync.
const horizon = 3600;
const pad = (n) => String(n).padStart(2, '0');
const say = (s) => {
  const a = Math.abs(s);
  const h = Math.floor(a / 3600);
  const m = Math.floor((a % 3600) / 60);
  const sec = Math.floor(a % 60);
  const t = h ? `${h}:${pad(m)}:${pad(sec)}` : `${pad(m)}:${pad(sec)}`;
  return s < 0 ? `已过 ${t}` : t;
};
const tick = () => {
  const now = Date.now() / 1000;
  for (const row of rows) {
    const left = row.dataset.at - now;
    row.classList.toggle('late', left < 0);
    row.querySelector('.cd-fill').style.width = `${Math.max(0, Math.min(1, 1 - left / horizon)) * 100}%`;
    row.querySelector('.cd-left').textContent = say(left);
  }
};

tick();
const timer = setInterval(tick, 1000);
return () => clearInterval(timer);

options.getOption:
const theme = context.grafana.theme;
const states = [
  ['无', '#8E8E8E'],
  ['失败', '#F2495C'],
  ['成功', '#73BF69'],
  ['同步中', '#56A64B'],
  ['准备同步', '#96D98D'],
  ['暂停', '#FADE2A'],
  ['禁用', '#3D3D3D'],
];
// With several queries the value column is named per query, so take it by type.
const table = (ref) => {
  const frame = context.panel.data.series.find((s) => s.refId === ref);
  return (name) =>
    frame?.fields.find((f) => (name === 'Value' ? f.type === 'number' : f.name === name))?.values ?? [];
};
const mirror = table('A');
const worker = table('B');
const up = {};
worker('worker').forEach((w, i) => {
  up[w] = worker('Value')[i] === 1;
});

const groups = {};
const codes = mirror('Value');
const owners = mirror('worker');
mirror('mirror').forEach((name, i) => {
  const [state, color] = states[codes[i]] ?? states[0];
  (groups[owners[i]] ??= []).push({
    name,
    value: state,
    symbolSize: 9,
    itemStyle: { color, borderColor: color },
  });
});

const workers = Object.entries(groups).map(([name, children]) => ({
  name,
  value: up[name] === false ? '离线' : '在线',
  symbolSize: 16,
  itemStyle: { color: up[name] === false ? '#F2495C' : '#5794F2', borderColor: theme.colors.background.primary, borderWidth: 2 },
  label: { fontSize: 13, fontWeight: 600 },
  children: children.sort((a, b) => a.name.localeCompare(b.name)),
}));

return {
  tooltip: { formatter: (p) => (p.data.value ? `${p.name}<br/>${p.data.value}` : p.name) },
  series: [
    {
      type: 'tree',
      layout: 'radial',
      data: [
        {
          name: 'manager',
          symbolSize: 22,
          itemStyle: { color: '#B877D9', borderColor: theme.colors.background.primary, borderWidth: 3 },
          label: { fontSize: 14, fontWeight: 600 },
          children: workers,
        },
      ],
      top: '15%',
      bottom: '15%',
      symbol: 'circle',
      initialTreeDepth: -1,
      expandAndCollapse: true,
      roam: 'scale',
      label: { color: theme.colors.text.primary, fontSize: 11 },
      lineStyle: { color: theme.colors.border.medium, width: 1.2, curveness: 0.4 },
      emphasis: { focus: 'relative' },
      animationDuration: 600,
    },
  ],
};
